(4119601, 591224, 83590, '<td valign="top">Yes. Enchanting. Dreamy. Draws you in. Colour. I just want to keep looking. Brilliant work.</td>', 'Yes. Enchanting. Dreamy. Draws you in. Colour. I just want to keep looking. Brilliant work.', '2007-09-27 07:28:04.000000', NULL, 1),
