(4119830, 590456, 66597, '<td valign="top">Don''t know if this is soft focus in the traditional sense, but I really love this photo. So you get a high score from me.</td>', 'Don''t know if this is soft focus in the traditional sense, but I really love this photo. So you get a high score from me.', '2007-09-27 10:33:54.000000', NULL, 1),
(4119834, 591453, 66597, '<td valign="top">He''s so pretty! There does appear to be a gothic glow action type effect on this, hopefully you did it in camera! Hope you''ll post how so the rest of us can learn :-)</td>', 'He''s so pretty! There does appear to be a gothic glow action type effect on this, hopefully you did it in camera! Hope you''ll post how so the rest of us can learn :-)', '2007-09-27 10:35:33.000000', NULL, 1),
