(4135068, 591028, 50695, '<td valign="top">Gorgeous. Like sunlight, Librodo models are easier to take when they''re screened off.</td>', 'Gorgeous. Like sunlight, Librodo models are easier to take when they''re screened off.', '2007-10-02 23:14:19.000000', NULL, 1),
(4135070, 591828, 67697, '<td valign="top">lol I guess this is one way to make a prickly fence look soft and inviting.  I''m sure anyone trying to scale it would think otherwise.</td>', 'lol I guess this is one way to make a prickly fence look soft and inviting.  I''m sure anyone trying to scale it would think otherwise.', '2007-10-02 23:14:26.000000', NULL, 1),
(4135075, 589320, 67697, '<td valign="top">I just find this to be such a quirky, funny photo.  But no, I cannot read the finger print lol. (7)</td>', 'I just find this to be such a quirky, funny photo.  But no, I cannot read the finger print lol. (7)', '2007-10-02 23:15:12.000000', NULL, 1),
