(4135108, 591727, 14620, '<td valign="top">Gorgeous, gorgeous light and the colors are splendid.  Nice wide angle composition to round out the top of the frame.</td>', 'Gorgeous, gorgeous light and the colors are splendid.  Nice wide angle composition to round out the top of the frame.', '2007-10-02 23:21:26.000000', NULL, 1),
(4135117, 590348, 14620, '<td valign="top">Very nice light and a beautiful orchid.  It just pops against the white background, perfect amount of softness.</td>', 'Very nice light and a beautiful orchid.  It just pops against the white background, perfect amount of softness.', '2007-10-02 23:22:23.000000', NULL, 1),
