INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4135644, 591070, 34462, '<td valign="top">Wow. I like this a lot. Wonderful colors and a great autumn feel. This should have definitley scored much better.</td>', 'Wow. I like this a lot. Wonderful colors and a great autumn feel. This should have definitley scored much better.', '2007-10-03 01:05:14.000000', NULL, 0),
(4135663, 591410, 33068, '<td valign="top">What a bummer.  I figured this would be the blue for sure.  Outstanding image.</td>', 'What a bummer.  I figured this would be the blue for sure.  Outstanding image.', '2007-10-03 01:08:23.000000', NULL, 0),
(4135672, 591372, 3724, '<td valign="top">DQ letter<br/>Tuesday, October 02, 2007 4:50 PM<br/> <br/>Hi Andre,<br/> <br/>Unfortunately, while the sharpening step was applied in Normal Mode, your image also included an illegal Background Copy layer. In Basic Editing, we can only use straight Adjustment Layers (ones that don''t contain pixel data).<br/> <br/>We''re so sorry, but the image has to be disqualified.<br/> <br/>L2, for DPC Site Council<br/></td>', 'DQ letterTuesday, October 02, 2007 4:50 PM Hi Andre, Unfortunately, while the sharpening step was applied in Normal Mode, your image also included an illegal Background Copy layer. In Basic Editing, we can only use straight Adjustment Layers (ones that don''t contain pixel data). We''re so sorry, but the image has to be disqualified. L2, for DPC Site Council', '2007-10-03 01:10:08.000000', NULL, 0),
(4135678, 591817, 23002, '<td valign="top">bummer on the DQ, but it is in the rules. :(</td>', 'bummer on the DQ, but it is in the rules. :(', '2007-10-03 01:11:17.000000', NULL, 0),
