(4143464, 590496, 76585, '<td valign="top">Great shot,I like the perspective,color and softness.If I had voted this challenge, 10 for sure.Sorry I missed it.</td>', 'Great shot,I like the perspective,color and softness.If I had voted this challenge, 10 for sure.Sorry I missed it.', '2007-10-05 08:47:44.000000', NULL, 0),
