(4144042, 589614, 27482, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tenfrozentoes:</b></div><hr/><i> Well we''ll have to see if I am able to get my original to them in time. Request for validation has been made. (???) Not sure why but no problem- as long as I get it to them in time. </i></td></tr></table> <br/> <br/>All top 5 images in all challenges are always validated so it´s just automatic.  Congrats on the ribbon!</td>', 'Originally posted by tenfrozentoes: Well we''ll have to see if I am able to get my original to them in time. Request for validation has been made. (???) Not sure why but no problem- as long as I get it to them in time.   All top 5 images in all challenges are always validated so it´s just automatic.  Congrats on the ribbon!', '2007-10-05 11:55:13.000000', NULL, 0),
(4144044, 589950, 27482, '<td valign="top">Congrats on the ribbon!</td>', 'Congrats on the ribbon!', '2007-10-05 11:55:46.000000', NULL, 0),
(4144309, 591703, 1570, '<td valign="top">just saw it today at Digital Image Cafe, wonderful work... i am sure that it will get a photo of the month there! these soft flowing whites are absolutely mesmerizing... and your courageous choice to cover her eyes paid off, too...</td>', 'just saw it today at Digital Image Cafe, wonderful work... i am sure that it will get a photo of the month there! these soft flowing whites are absolutely mesmerizing... and your courageous choice to cover her eyes paid off, too...', '2007-10-05 13:30:26.000000', NULL, 0),
(4144341, 591703, 46177, '<td valign="top">This is a stunning shot, congratulations!</td>', 'This is a stunning shot, congratulations!', '2007-10-05 13:37:50.000000', NULL, 0),
(4144712, 589614, 34562, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Larus:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tenfrozentoes:</b></div><hr/><i> Well we''ll have to see if I am able to get my original to them in time. Request for validation has been made. (???) Not sure why but no problem- as long as I get it to them in time. </i></td></tr></table> <br/> <br/>All top 5 images in all challenges are always validated so it´s just automatic.  Congrats on the ribbon! </i></td></tr></table> <br/> <br/>That''s what I figured but wasn''t too sure either- not a problem that they''re asking to validate the original just that I moved to NY and then had to immediately repack all my stuff and move again. My desktop computer is still packed away and of course it''s in the very front of the trailer-lol. Hopefully I''ll be able to dig it out tonight- gonna break me if it gets DQ''d now. :(</td>', 'Originally posted by Larus: Originally posted by tenfrozentoes: Well we''ll have to see if I am able to get my original to them in time. Request for validation has been made. (???) Not sure why but no problem- as long as I get it to them in time.   All top 5 images in all challenges are always validated so it´s just automatic.  Congrats on the ribbon!   That''s what I figured but wasn''t too sure either- not a problem that they''re asking to validate the original just that I moved to NY and then had to immediately repack all my stuff and move again. My desktop computer is still packed away and of course it''s in the very front of the trailer-lol. Hopefully I''ll be able to dig it out tonight- gonna break me if it gets DQ''d now. :(', '2007-10-05 15:28:09.000000', NULL, 0),
(4146507, 591798, 42013, '<td valign="top">Otherworldly. Great title to go with it.</td>', 'Otherworldly. Great title to go with it.', '2007-10-06 02:31:53.000000', NULL, 0),
(4147176, 591798, 41047, '<td valign="top">this is so beautiful. i agree with erin and yanko, this has a very serene dream-like look, yet makes you feel claustrophobic at the same time. i love this contrast. briliant capture to achieve this balance.</td>', 'this is so beautiful. i agree with erin and yanko, this has a very serene dream-like look, yet makes you feel claustrophobic at the same time. i love this contrast. briliant capture to achieve this balance.', '2007-10-06 14:19:41.000000', NULL, 0),
(4148160, 591703, 30861, '<td valign="top">This is just exceptionally good. The various textures of the whites are stunning, and that''s SO hard to do. Also, kudos for HIDING THE EYES! That was so brave, and it absolutely takes the image to the next level. Congrats!</td>', 'This is just exceptionally good. The various textures of the whites are stunning, and that''s SO hard to do. Also, kudos for HIDING THE EYES! That was so brave, and it absolutely takes the image to the next level. Congrats!', '2007-10-06 23:59:16.000000', NULL, 0),
(4148650, 589160, 73564, '<td valign="top">cute picure</td>', 'cute picure', '2007-10-07 03:46:39.000000', NULL, 0),
(4148810, 590542, 66548, '<td valign="top">WOW!</td>', 'WOW!', '2007-10-07 08:18:35.000000', NULL, 0),
