(4150043, 591224, 64176, '<td valign="top">I expect Liv Tyler to come walking down that path any moment... lovely and ethereal!  Congrats on 10th place!</td>', 'I expect Liv Tyler to come walking down that path any moment... lovely and ethereal!  Congrats on 10th place!', '2007-10-07 21:15:43.000000', NULL, 0),
(4150058, 591112, 64176, '<td valign="top">My shopping list:  one fine red mesh pot potpourri net bag thingy... i already have 6 cats and i can borrow a cute little blonde girl from my sister-in-law.  :-)  (Beeeeeautiful image and i''m glad no dumb-asses gave you a 3 or lower.  Ten 4''s though--those are the DPC crack smokers...)</td>', 'My shopping list:  one fine red mesh pot potpourri net bag thingy... i already have 6 cats and i can borrow a cute little blonde girl from my sister-in-law.  :-)  (Beeeeeautiful image and i''m glad no dumb-asses gave you a 3 or lower.  Ten 4''s though--those are the DPC crack smokers...)', '2007-10-07 21:21:55.000000', NULL, 0),
(4150737, 591590, 30861, '<td valign="top">Whatta joke this score is! I had this terrifically emotive, mysterious image as one of my 5 top picks. You done real well :-)</td>', 'Whatta joke this score is! I had this terrifically emotive, mysterious image as one of my 5 top picks. You done real well :-)', '2007-10-08 02:03:16.000000', NULL, 0),
(4150820, 591703, 78255, '<td valign="top">I don''t see how anyone could rate this anything other than a 10. This is a magnificent image. The technical camera work and artistic appeal is outstanding.</td>', 'I don''t see how anyone could rate this anything other than a 10. This is a magnificent image. The technical camera work and artistic appeal is outstanding.', '2007-10-08 02:56:36.000000', NULL, 0),
(4150974, 591574, 39825, '<td valign="top">hey, beautiful!!! and also a new profile-photo! ;-)</td>', 'hey, beautiful!!! and also a new profile-photo! ;-)', '2007-10-08 04:50:11.000000', NULL, 0),
(4151118, 591410, 44579, '<td valign="top">Funny how we have both entered pictures of her, very similar backdrop, and no flash. I am definitely realizing that not every shot needs off camera flash.</td>', 'Funny how we have both entered pictures of her, very similar backdrop, and no flash. I am definitely realizing that not every shot needs off camera flash.', '2007-10-08 06:46:13.000000', NULL, 0),
